/**
 * @file red_black_tree.hpp
 * @brief A dense, heavily commented implementation of a Red-Black Tree in C++.
 * 
 * Red-Black Trees are self-balancing binary search trees that guarantee
 * O(log n) worst-case performance for search, insert, and delete operations.
 * They are a common choice for implementations of associative containers
 * (e.g., std::map, std::set) in many standard libraries.
 * 
 * Properties maintained by a Red-Black Tree:
 * 1. Every node is either red or black.
 * 2. The root is always black.
 * 3. All leaves (NIL nodes) are black.
 * 4. If a node is red, then both its children are black (no two consecutive
 *    red nodes on any path from a node to a descendant).
 * 5. For each node, all paths from the node to descendant leaves contain
 *    the same number of black nodes (black-height).
 * 
 * This implementation uses explicit NIL nodes (sentinels) to simplify
 * rotation and rebalancing logic. The tree is templated on the key type.
 */

#include <iostream>
#include <functional>
#include <memory>
#include <algorithm>
#include <stdexcept>
#include <cassert>
#include <string>

namespace rbt {

/**
 * @enum Color
 * @brief Enumeration for the color of a node in a Red-Black Tree.
 */
enum class Color {
    RED,
    BLACK
};

/**
 * @class Node
 * @brief Represents a node in the Red-Black Tree.
 * 
 * Each node stores a key, a pointer to its parent, left child, right child,
 * and its color. We use a shared pointer to the NIL node to represent
 * null leaves, which simplifies boundary checks.
 */
template <typename Key>
struct Node {
    Key key;
    Color color;
    std::shared_ptr<Node> parent;
    std::shared_ptr<Node> left;
    std::shared_ptr<Node> right;

    /**
     * @brief Constructor for a node.
     * @param k The key to store in this node.
     * @param c The initial color of the node.
     * @param parent The parent node.
     * @param left The left child.
     * @param right The right child.
     */
    Node(const Key& k, Color c, std::shared_ptr<Node> parent,
         std::shared_ptr<Node> left, std::shared_ptr<Node> right)
        : key(k), color(c), parent(parent), left(left), right(right) {}
};

/**
 * @class RedBlackTree
 * @brief A templated Red-Black Tree supporting insert, erase, and find.
 * 
 * This class manages the structure and balancing of the tree. It maintains
 * a root pointer and a NIL sentinel node.
 */
template <typename Key>
class RedBlackTree {
private:
    std::shared_ptr<Node<Key>> root_;
    std::shared_ptr<Node<Key>> nil_; // Sentinel NIL node (black)

    /**
     * @brief Performs a left rotation around node x.
     * 
     * Left rotation is a fundamental operation in binary search trees.
     * It restructures the tree to maintain the BST property while
     * moving node x down and its right child up.
     * 
     * Diagram:
       Before:          After:
           x               y
          / \            / \
         T1   y         x   T3
            / \        / \
           T2  T3     T1  T2
     * 
     * @param x The node around which to rotate left.
     */
    void rotateLeft(std::shared_ptr<Node<Key>> x) {
        if (!x || x == nil_) return;

        // y is the right child of x
        std::shared_ptr<Node<Key>> y = x->right;

        // y's left child becomes x's right child
        x->right = y->left;
        if (y->left != nil_) {
            y->left->parent = x;
        }

        // y's parent becomes x's parent
        y->parent = x->parent;

        if (x->parent == nil_) {
            root_ = y;
        } else if (x == x->parent->left) {
            x->parent->left = y;
        } else {
            x->parent->right = y;
